<script setup lang="ts">
import { ref, computed } from 'vue'
import { onLoad } from '@dcloudio/uni-app'
import { useTournament } from '@/composables/useTournament'
import { findTeam, participantLabel, stageNames, statusNames, dateLabel } from '@/domain/tournament'
import AppShell from '@/components/AppShell.vue'
import AppIcon from '@/components/AppIcon.vue'
import TeamBadge from '@/components/TeamBadge.vue'
const { data, matches, error, load } = useTournament()
const id = ref(''), tab = ref('overview')
onLoad(query => { id.value = query?.id || '' })
const match = computed(() => matches.value.find(m => m.id === id.value))
const statRows = computed(() => {
  const s = match.value?.stats
  return s ? [{ label: '控球率', values: s.possession, suffix: '%' }, { label: '射门', values: s.shots, suffix: '' }, { label: '射正', values: s.shotsOnTarget, suffix: '' }, { label: '角球', values: s.corners, suffix: '' }] : []
})
const eventLabels = { goal: '进球', yellow: '黄牌', substitution: '换人' }
function playerName(playerId?: string) { return data.value?.players.find(p => p.id === playerId)?.name || '未记录球员' }
function team(id: string | null) { if (id) uni.navigateTo({ url: `/pages/team/detail?id=${id}` }) }
function back() { uni.navigateBack({ fail: () => uni.reLaunch({ url: '/pages/index/index?tab=tournament' }) }) }
</script>
<template><AppShell active="tournament" detail><view v-if="data && match" class="inner-page match-detail-page"><button hover-class="none" role="button" tabindex="0" class="ui-button breadcrumb" @click="back"><AppIcon name="back" :size="15"/>返回赛事<text>/ 比赛详情</text></button><view class="match-detail-hero"><view class="detail-match-top"><text>{{ data.name }} · {{ stageNames[match.stage] }}</text><view class="detail-status"><view v-if="match.status === 'live'" class="live-dot"/>{{ statusNames[match.status] }} {{ match.minute ? `${match.minute}′` : '' }}</view></view><view class="detail-scoreboard"><button hover-class="none" role="button" tabindex="0" class="ui-button detail-team" @click="team(match.homeId)"><TeamBadge :team="findTeam(data, match.homeId)" :size="82"/><text>{{ participantLabel(match, 'home', data) }}</text><text class="team-detail-link">{{ match.homeId ? '球队主页 →' : '晋级结果待定' }}</text></button><view class="detail-score"><text v-if="match.homeScore !== null">{{ match.homeScore }}<text class="detail-score-colon">:</text>{{ match.awayScore }}</text><text v-else class="detail-vs">VS</text><text class="detail-score-label">{{ match.status === 'live' ? '模拟进行中 · 非实时直播' : match.status === 'finished' ? '全场比分 · 演示数据' : '等待开场 · 演示赛程' }}</text></view><button hover-class="none" role="button" tabindex="0" class="ui-button detail-team" @click="team(match.awayId)"><TeamBadge :team="findTeam(data, match.awayId)" :size="82"/><text>{{ participantLabel(match, 'away', data) }}</text><text class="team-detail-link">{{ match.awayId ? '球队主页 →' : '晋级结果待定' }}</text></button></view><view class="detail-match-bottom"><view><AppIcon name="calendar" :size="15" tone="white"/>{{ dateLabel(match.date) }} {{ match.time }}</view><view><AppIcon name="pin" :size="15" tone="white"/>{{ match.venue }}</view></view></view><view class="page-tabs"><button hover-class="none" role="button" tabindex="0" class="ui-button" :class="{ active: tab === 'overview' }" @click="tab = 'overview'">比赛概况</button><button hover-class="none" role="button" tabindex="0" class="ui-button" :class="{ active: tab === 'stats' }" @click="tab = 'stats'">技术统计</button><button hover-class="none" role="button" tabindex="0" class="ui-button" :class="{ active: tab === 'events' }" @click="tab = 'events'">赛场事件</button></view><view class="match-detail-grid"><view v-if="tab !== 'events'" class="panel detail-stat-panel"><view class="section-heading"><text class="h2">技术统计</text><text class="muted small-text">模拟统计</text></view><view v-if="statRows.length" class="stat-bars"><view v-for="row in statRows" :key="row.label" class="stat-bar-row"><view><text>{{ row.values[0] }}{{ row.suffix }}</text><text class="muted">{{ row.label }}</text><text>{{ row.values[1] }}{{ row.suffix }}</text></view><view class="stat-track"><view :style="{ width: `${row.values[0] / (row.values[0] + row.values[1] || 1) * 100}%` }"/><view :style="{ width: `${row.values[1] / (row.values[0] + row.values[1] || 1) * 100}%` }"/></view></view></view><view v-else class="empty-state"><AppIcon name="clock" :size="35" tone="muted"/><text>比赛尚未开始</text><text class="muted small-text">开赛后，技术统计会出现在这里</text></view></view><view v-if="tab !== 'stats'" class="panel timeline-panel"><view class="section-heading"><text class="h2">赛场时间轴</text><text class="muted small-text">{{ match.events.length }} 条事件</text></view><view v-if="match.events.length" class="event-timeline"><view v-for="event in match.events" :key="event.id" class="timeline-event"><text class="event-minute">{{ event.minute }}′</text><view class="event-marker"><AppIcon :name="event.kind === 'goal' ? 'ball' : 'flag'" tone="green" :size="19"/></view><view class="event-copy"><text class="h3">{{ playerName(event.playerId) }}<text class="event-kind">{{ eventLabels[event.kind] }}</text></text><text class="muted small-text">{{ findTeam(data, event.teamId)?.name }}<text v-if="event.assistPlayerId"> · {{ playerName(event.assistPlayerId) }} 助攻</text></text></view></view></view><view v-else class="empty-state"><AppIcon name="ball" :size="35" tone="muted"/><text>精彩，等待开场</text><text class="muted small-text">暂无已记录的比赛事件</text></view></view></view><view class="inline-note"><AppIcon name="info" tone="muted" :size="16"/><text>本场比赛为虚构演示。比分、事件与球队数据来自同一份本地资料，不提供实时直播或实际场地导航。</text></view></view><view v-else-if="error" class="empty-state"><text>{{ error }}</text><button hover-class="none" role="button" tabindex="0" class="ui-button primary-button" @click="load">重新加载</button></view><view v-else-if="data" class="empty-state"><text class="h2">没有找到这场比赛</text><button hover-class="none" role="button" tabindex="0" class="ui-button primary-button" @click="back">返回赛事</button></view><view v-else class="loading-state">正在加载比赛…</view></AppShell></template>
